# WAR ARENA - Signature Intelligence Indices (WAR Analysis engine) - Installer
# Adds src/product/analysis/warIndices.ts: 9 deterministic indices + WAR SCORE.
# Absorption, Concentration, Organic, Sniper load, Smart conviction,
# Contract integrity, Flow balance, Turnover, ATH position.
# Every index carries its own formula; insufficient inputs are excluded, never faked.
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-war-indices.ps1
$ErrorActionPreference = "Stop"
Write-Host "WAR - signature indices installer" -ForegroundColor Cyan
function Write-B64([string]$Path,[string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($Path,[System.Convert]::FromBase64String($B64))
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 "src/product/analysis/warIndices.ts" ""
Write-B64 "src/integration/gmgnTrendingSource.ts" ""
Write-B64 "tests/unit/warIndices.test.ts" ""

Write-Host ""; Write-Host "Verifying ..." -ForegroundColor Cyan
npx tsc --noEmit; if ($LASTEXITCODE -ne 0){ throw "typecheck failed" }
npx vitest run
npm run build; if ($LASTEXITCODE -ne 0){ throw "build failed" }
Write-Host ""; Write-Host "WAR indices installed. Expected: 1083 passed + 1 skipped, 493 guards." -ForegroundColor Green
Write-Host "Restart: npm start" -ForegroundColor Yellow
